package rng

import "testing"

// Vectors evaluated from the unchanged HTML's hashStr and mulberry32, not
// generated by the Go implementation. See docs/phase-1/VALIDATION.md.
func TestHashStrLegacyVectors(t *testing.T) {
	for _, v := range []struct {
		input string
		want  uint32
	}{
		{"", 2166136261}, {"1", 873244444}, {"world:Asabiya", 4037141429},
		{"México", 612256362}, {"🌍", 3962535490}, {"hist:1:Asabiya", 58464154},
	} {
		if got := HashStr(v.input); got != v.want {
			t.Errorf("HashStr(%q)=%d, want %d", v.input, got, v.want)
		}
	}
}

func TestMulberry32LegacyVectors(t *testing.T) {
	for _, v := range []struct {
		seed uint32
		want [8]uint32
	}{
		{0, [8]uint32{1144304738, 1416247, 958946056, 627933444, 2007157716, 2340967985, 2642484575, 2787370982}},
		{1, [8]uint32{2693262067, 11749833, 2265367787, 4213581821, 4159151403, 1207330352, 2632122864, 3095568220}},
		{0xffffffff, [8]uint32{3850105811, 813802916, 3073704848, 4054706436, 3630262831, 2315588663, 2922715533, 2042566601}},
		{123456789, [8]uint32{1107202814, 4169434471, 3372958138, 885470128, 1301683845, 3208624240, 3344635568, 1221959552}},
	} {
		r := New(v.seed)
		for i, want := range v.want {
			if got := r.Uint32(); got != want {
				t.Errorf("seed %d draw %d: %d, want %d", v.seed, i, got, want)
			}
		}
		if r.Position() != (Position{Seed: v.seed, Calls: 8}) {
			t.Fatal("incorrect RNG position")
		}
		f := New(v.seed)
		for _, want := range v.want {
			if f.Float64() != float64(want)/4294967296 {
				t.Fatal("float draw differs")
			}
		}
	}
}

func TestRestoreAcrossStateWrap(t *testing.T) {
	r := New(0xfffffff0)
	for i := 0; i < 100003; i++ {
		r.Uint32()
	}
	restored := Restore(r.Position())
	for i := 0; i < 100; i++ {
		if restored.Uint32() != r.Uint32() {
			t.Fatal("restored continuation differs")
		}
	}
	// The generator has period 2^32; the call counter itself must not wrap.
	a := Restore(Position{Seed: 42, Calls: 1<<32 + 17})
	b := Restore(Position{Seed: 42, Calls: 17})
	if a.Uint32() != b.Uint32() || a.Position().Calls != (1<<32+18) {
		t.Fatal("wide call counter lost")
	}
}
